fn unique_id(label: &str) -> String {
    let nanos = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap()
        .as_nanos();
    format!("node-sync-{label}-{nanos}")
}

fn now_rfc3339() -> String {
    time::OffsetDateTime::now_utc()
        .format(&time::format_description::well_known::Rfc3339)
        .unwrap()
}

/// A deterministic-per-label Ed25519 key. Distinct labels always produce
/// distinct keys, which is all these tests need (never real key material).
fn signing_key_from_label(label: &str) -> SigningKey {
    let seed: [u8; 32] = Sha256::digest(label.as_bytes()).into();
    SigningKey::from_bytes(&seed)
}

/// Real `NodeEnrollmentService` and `NodeSyncService` instances on an
/// ephemeral loopback port. The server stops when this value is dropped.
struct TestServer {
    endpoint: String,
    _shutdown: oneshot::Sender<()>,
}

async fn start_server(database_url: &str) -> TestServer {
    let enrollment_store = EnrollmentStore::connect(database_url)
        .await
        .expect("the gated test database should accept enrollment migrations");
    let ledger = LedgerStore::connect(database_url)
        .await
        .expect("the gated test database should accept ledger migrations");
    let work_store = WorkStore::connect(database_url)
        .await
        .expect("the gated test database should accept Work migrations");

    let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
        .await
        .expect("the test service should bind loopback");
    let address = listener.local_addr().unwrap();
    let (shutdown_tx, shutdown_rx) = oneshot::channel();
    tokio::spawn(async move {
        Server::builder()
            .add_service(NodeEnrollmentServiceServer::new(
                NodeEnrollmentService::new(enrollment_store),
            ))
            .add_service(NodeSyncServiceServer::new(
                NodeSyncService::with_work_store(
                    ledger,
                    work_store,
                    v1::FlowControl {
                        max_in_flight_batches: 16,
                        max_batch_bytes: 1_048_576,
                    },
                ),
            ))
            .serve_with_incoming_shutdown(TcpListenerStream::new(listener), async {
                let _ = shutdown_rx.await;
            })
            .await
            .expect("the test service should run");
    });

    TestServer {
        endpoint: format!("http://{address}"),
        _shutdown: shutdown_tx,
    }
}

/// One genuinely enrolled and activated node -- everything
/// `NodeSyncConnection::open` needs to authenticate for real, produced the
/// same way an external node would: submit, approve, challenge, activate.
struct EnrolledNode {
    tenant_id: String,
    repository_id: String,
    node_id: String,
    signing_key: SigningKey,
    signing_key_id: String,
}

async fn enroll_and_activate(endpoint: &str, database_url: &str) -> EnrolledNode {
    let tenant_id = unique_id("tenant");
    let repository_id = unique_id("repository");
    let node_id = unique_id("node");
    let request_id = unique_id("request");
    let signing_key = signing_key_from_label(&node_id);
    let public_key = signing_key.verifying_key().to_bytes().to_vec();
    let fingerprint = public_key_fingerprint(&public_key);

    let mut enrollment_client = NodeEnrollmentServiceClient::connect(endpoint.to_string())
        .await
        .expect("the in-process enrollment service should accept the connection");

    enrollment_client
        .submit_enrollment_request(Request::new(v1::EnrollmentRequest {
            request_id: request_id.clone(),
            tenant_id: tenant_id.clone(),
            repository_id: repository_id.clone(),
            proposed_node_id: node_id.clone(),
            display_name: "node sync handshake test node".to_string(),
            public_key_fingerprint: fingerprint.clone(),
            requested_capabilities: vec!["synchronize".to_string()],
            created_at: now_rfc3339(),
            expires_at: "2030-01-01T00:00:00Z".to_string(),
            public_key: public_key.clone(),
        }))
        .await
        .expect("submit_enrollment_request should round-trip over the wire");

    let mut store = EnrollmentStore::connect(database_url)
        .await
        .expect("the gated test database should accept an enrollment connection");
    store
        .approve(&EnrollmentApproval {
            request_id: request_id.clone(),
            tenant_id: tenant_id.clone(),
            repository_id: repository_id.clone(),
            public_key_fingerprint: fingerprint.clone(),
            approved_capabilities: vec!["synchronize".to_string()],
            approved_by: "test-administrator".to_string(),
        })
        .await
        .expect("approval should succeed for a pending request");

    let challenge = enrollment_client
        .get_activation_challenge(Request::new(v1::EnrollmentChallengeRequest {
            request_id: request_id.clone(),
            tenant_id: tenant_id.clone(),
            repository_id: repository_id.clone(),
            proposed_node_id: node_id.clone(),
            public_key_fingerprint: fingerprint.clone(),
        }))
        .await
        .expect("an approved request should be issued a real activation challenge")
        .into_inner();
    let proof_bytes = activation_challenge_bytes(
        &challenge.nonce,
        &request_id,
        &tenant_id,
        &repository_id,
        &node_id,
        &fingerprint,
    );
    let activation = enrollment_client
        .activate_enrollment(Request::new(v1::EnrollmentActivationProof {
            request_id: request_id.clone(),
            tenant_id: tenant_id.clone(),
            repository_id: repository_id.clone(),
            proposed_node_id: node_id.clone(),
            public_key_fingerprint: fingerprint.clone(),
            nonce: challenge.nonce.clone(),
            signature: signing_key.sign(&proof_bytes).to_bytes().to_vec(),
        }))
        .await
        .expect("activation with a genuine proof of possession should succeed")
        .into_inner();

    EnrolledNode {
        tenant_id,
        repository_id,
        node_id,
        signing_key,
        signing_key_id: activation.signing_key_id,
    }
}

fn refusal_reason(error: ClientError) -> RejectionReason {
    match error {
        ClientError::ConnectionRefused { reason, .. } => reason,
        other => panic!("expected ConnectionRefused, got {other:?}"),
    }
}

/// `NodeSyncConnection` does not implement `Debug` (it owns a live
/// `Streaming` response body), so a refusal is asserted by matching directly
/// rather than through `Result::expect_err`.
async fn expect_refused(
    result: Result<NodeSyncConnection, ClientError>,
    context: &str,
) -> RejectionReason {
    match result {
        Ok(_) => panic!("{context}"),
        Err(error) => refusal_reason(error),
    }
}

#[tokio::test]
async fn a_fresh_enrolled_node_authenticates_and_opens_a_connection() {
    let Ok(database_url) = std::env::var("ACKPLANE_TEST_DATABASE_URL") else {
        println!("skipped: ACKPLANE_TEST_DATABASE_URL not set");
        return;
    };
    let server = start_server(&database_url).await;
    let node = enroll_and_activate(&server.endpoint, &database_url).await;
    let signer = SeedSigner::new(
        node.signing_key_id.clone(),
        node.node_id.clone(),
        &node.signing_key.to_bytes(),
    );

    let connection = NodeSyncConnection::open(
        &server.endpoint,
        &signer,
        &node.tenant_id,
        &node.repository_id,
        vec!["synchronize".to_string()],
        0,
    )
    .await
    .expect("a genuinely enrolled and activated node should authenticate");

    assert_eq!(connection.accepted_position(), 0);
    assert_eq!(connection.flow_control().max_in_flight_batches, 16);
}

#[tokio::test]
async fn a_wrong_signature_is_refused_as_unauthenticated() {
    let Ok(database_url) = std::env::var("ACKPLANE_TEST_DATABASE_URL") else {
        println!("skipped: ACKPLANE_TEST_DATABASE_URL not set");
        return;
    };
    let server = start_server(&database_url).await;
    let node = enroll_and_activate(&server.endpoint, &database_url).await;
    // Claims the enrolled node's own signing_key_id, but signs with a
    // different key it never enrolled -- the impostor scenario a challenge
    // response exists to catch.
    let impostor_key = signing_key_from_label("impostor");
    let signer = SeedSigner::new(
        node.signing_key_id.clone(),
        node.node_id.clone(),
        &impostor_key.to_bytes(),
    );

    let error = expect_refused(
        NodeSyncConnection::open(
            &server.endpoint,
            &signer,
            &node.tenant_id,
            &node.repository_id,
            vec!["synchronize".to_string()],
            0,
        )
        .await,
        "a signature from the wrong key must be refused, not silently accepted",
    )
    .await;

    assert_eq!(error, RejectionReason::Unauthenticated);
}

