#[tokio::test]
async fn a_revoked_key_is_refused_as_node_revoked() {
    let Ok(database_url) = std::env::var("ACKPLANE_TEST_DATABASE_URL") else {
        println!("skipped: ACKPLANE_TEST_DATABASE_URL not set");
        return;
    };
    let server = start_server(&database_url).await;
    let node = enroll_and_activate(&server.endpoint, &database_url).await;

    let (mut client, connection) = tokio_postgres::connect(&database_url, tokio_postgres::NoTls)
        .await
        .expect("the gated test database should accept a raw connection");
    tokio::spawn(async move {
        let _ = connection.await;
    });
    let transaction = client.transaction().await.expect("begin transaction");
    signing_keys::revoke(
        &transaction,
        &KeyRevocation {
            signing_key_id: node.signing_key_id.clone(),
            reason: "node_sync_handshake test revocation".to_owned(),
        },
        SystemTime::now(),
    )
    .await
    .expect("revoke the test key");
    transaction.commit().await.expect("commit the revocation");

    let signer = SeedSigner::new(
        node.signing_key_id.clone(),
        node.node_id.clone(),
        &node.signing_key.to_bytes(),
    );
    let error = expect_refused(
        NodeSyncConnection::open(
            &server.endpoint,
            &signer,
            &node.tenant_id,
            &node.repository_id,
            vec!["synchronize".to_string()],
            0,
        )
        .await,
        "a revoked key must be refused even with a genuine signature",
    )
    .await;

    assert_eq!(error, RejectionReason::NodeRevoked);
}
